test('vatSummary calculates base and vat correctly', () => {
  const inv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 10 }],
    }).value,
    []
  ).value;

  const result = vatSummary([inv]);
  // DES-HOUR: unitPrice 8500, qty 10 = 85000
  // gold tier 5% discount: 85000 - 4250 = 80750
  // VAT 21%: roundCents(80750 * 0.21) = 16957
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 80750);
  assert.equal(result[0].vat, 16957);
});

