test('vatSummary aggregates across multiple invoices', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    }).value,
    []
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-08',
      lines: [{ sku: 'DES-HOUR', qty: 3 }],
    }).value,
    ['INV-2026-0001']
  ).value;

  const result = vatSummary([inv1, inv2]);
  // Both invoices have DES-HOUR (21% VAT), should aggregate
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // inv1: 42500 - 2125 = 40375 (gold tier 5%, vat 8479)
  // inv2: 25500 - 0 = 25500 (standard tier 0%, vat 5355)
  // base: 40375 + 25500 = 65875
  // vat: 8479 + 5355 = 13834
  assert.equal(result[0].base, 65875);
  assert.equal(result[0].vat, 13834);
});

